export type CloudFormationResource<
  TypeString extends string,
  AttributesType extends Record<any, any>,
  PropertiesType extends Record<any, any>,
> = {
  Type: TypeString;
  Attributes?: AttributesType & never;
  CreationPolicy?: {
    AutoScalingCreationPolicy?: {
      MinSuccessfulInstancesPercent?: number;
    };
    ResourceSignal?: {
      Count?: number;
      Timeout?: string;
    };
  };
  DeletionPolicy?: "Delete" | "Retain" | "Snapshot";
  DependsOn?: string | string[];
  Metadata?: Record<any, any>;
  UpdatePolicy?: {
    AutoScalingReplacingUpdate?: {
      WillReplace?: boolean;
    };
    AutoScalingRollingUpdate?: {
      MaxBatchSize?: number;
      MinInstancesInService?: number;
      MinSuccessfulInstancesPercent?: number;
      PauseTime?: string;
      SuspendProcesses?: {
        AutoScalingGroupName: string;
        ScalingProcesses?: (
          | "Launch"
          | "Terminate"
          | "AddToLoadBalancer"
          | "AlarmNotification"
          | "AZRebalance"
          | "HealthCheck"
          | "InstanceRefresh"
          | "ReplaceUnhealthy"
          | "ScheduledActions"
        )[];
      }[];
      WaitOnResourceSignals?: boolean;
    };
    AutoScalingScheduledAction?: {
      IgnoreUnmodifiedGroupSizeProperties?: boolean;
    };
    UseOnlineResharding?: boolean;
    EnableVersionUpgrade?: boolean;
    CodeDeployLambdaAliasUpdate?: {
      AfterAllowTrafficHook?: string;
      ApplicationName: string;
      BeforeAllowTrafficHook?: string;
      DeploymentGroupName: string;
    };
  };
  UpdateReplacePolicy?: "Delete" | "Retain" | "Snapshot";
  Condition?: any;
  Properties: PropertiesType;
};

